# Build a set of artist names for each old song and match against song details
old_song_keys = set()
for s in old_songs:
    key = (s['title'], frozenset(s['artists']))
    old_song_keys.add(key)

# Build mapping from song_id to details and also a key for each song
song_key_to_ids = {}
for sid, details in song_details.items():
    title = details['title']
    artists = {a['name'] for a in details['artists']}
    key = (title, frozenset(artists))
    if key not in song_key_to_ids:
        song_key_to_ids[key] = []
    song_key_to_ids[key].append(sid)

# Find matching song IDs
matched_song_ids = set()
for key in old_song_keys:
    if key in song_key_to_ids:
        for sid in song_key_to_ids[key]:
            matched_song_ids.add(sid)
            print(f"Matched: {key[0]} by {', '.join(sorted(key[1]))} -> song_id {sid}")
    else:
        print(f"No match for: {key[0]} by {', '.join(sorted(key[1]))}")

print(f"\nTotal matched songs: {len(matched_song_ids)}")

